# ledger mail.glance@1.0.0
theme taskplan_light
# level:   L0
# profile: ui/l0
#
# MAIL — reusable L0 compact glance card template (renders the L0 "glance"
# presentation depth; the language level stays L0).
#
# Synthetic demo fixture only: no mailbox is read and nothing is sent. Facts
# come from the catalogued `sys.dataset` source; the agent's summary is the
# card's own model-copy and never acts.

source msg sys.dataset(fields: [title, subtitle, as_of])

state mode { shape: enum[brief, archived], initial: .brief }

event archive { mode: set(.archived) }
event restore { mode: set(.brief) }
event reply   { mode: set(.brief) }
event open    { mode: set(.brief) }

copy app      { class: vocabulary, en: "Mail",   zh: "邮件" }
copy h_sum    { class: vocabulary, en: "SUMMARY" }
copy b_reply  { class: vocabulary, en: "Reply" }
copy b_open   { class: vocabulary, en: "Open ↗" }
copy b_arch   { class: vocabulary, en: "Archive" }
copy b_undo   { class: vocabulary, en: "Undo" }
copy archived { class: vocabulary, en: "Archived (demo)" }
copy loading  { class: vocabulary, en: "Loading…", zh: "加载中…" }
copy offline  { class: vocabulary, en: "Can't reach the network", zh: "网络不可用" }
copy empty    { class: vocabulary, en: "No messages" }
copy gist     { class: model-copy, en: "Ana wants to sign by Friday and asked for the revised payment terms first." }

view root Surface(pad: .tight) {
  Col(gap: 10) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.app, width: .fill)
      TextCaption(value: msg.as_of)
    }
    when msg.$state == .pending { TextBody(text: copy.loading) }
    when msg.$state == .failed  { TextBody(text: copy.offline) }
    when msg.$state == .ready {
      TextTitle(text: msg.title, width: .fill)
      TextBody(text: msg.subtitle, width: .fill)
      when mode == .brief {
        TextEyebrow(text: copy.h_sum)
        TextBody(text: copy.gist, width: .fill)
        Row(gap: 8) {
          Chip(text: copy.b_reply, on_tap: reply, tone: .primary)
          Chip(text: copy.b_arch, on_tap: archive)
          Chip(text: copy.b_open, on_tap: open)
        }
      }
      when mode == .archived {
        Row(gap: 8, align: .center) {
          Icon(name: .check, size: .row)
          TextTitle(text: copy.archived)
        }
        Chip(text: copy.b_undo, on_tap: restore, tone: .primary)
      }
    }
  }
}

// Mail Cards — native interactive preview of the MAIL card template.
// Shows all three UI presentation depths (L0 glance / L1 expanded / L2 app).
// Synthetic demo content only: no mailbox access, no network, nothing sent.

let depth = "glance"
let archived = false
let reply_text = ""
let sent_demo = false

let NavBtn = ButtonFlat{height: 44 padding: 12 draw_bg +: {color: #xe8edf3 color_hover: #xdde5ef color_down: #xd0dae7} draw_text +: {color: #x1c2430 color_hover: #x1c2430 color_down: #x1c2430}}
let AccentBtn = ButtonFlat{height: 44 padding: 14 draw_bg +: {color: #x2f6fed color_hover: #x3d7cf0 color_down: #x275fd0} draw_text +: {color: #xffffff color_hover: #xffffff color_down: #xffffff}}
let GhostBtn = ButtonFlat{height: 44 padding: 14 draw_bg +: {color: #xffffff color_hover: #xf0f4f8 color_down: #xe6ecf3} draw_text +: {color: #x1c2430 color_hover: #x1c2430 color_down: #x1c2430}}

fn depth_name(){
    if depth == "glance" { return "L0 glance" }
    if depth == "expand" { return "L1 expanded" }
    return "L2 app"
}

fn refresh_nav(){
    let s = "Depth: " + depth_name()
    if archived { s = s + "   ·   Archived (demo)" }
    ui.depth_status.set_text(s)
}

fn set_depth(d){
    depth = d
    sent_demo = false
    refresh_nav()
    ui.stage.render()
}

fn do_archive(){
    archived = true
    refresh_nav()
    ui.stage.render()
}

fn do_undo(){
    archived = false
    refresh_nav()
    ui.stage.render()
}

fn on_field(t){
    reply_text = t
}

fn do_send(){
    sent_demo = true
    ui.stage.render()
}

fn boot(){
    refresh_nav()
    ui.stage.render()
}

start_timeout(0.05, || boot())

SolidView{width: Fill height: Fill flow: Down padding: 16 spacing: 12 draw_bg.color: #xf4f6f8
    Label{text: "Mail Cards" draw_text.color: #x1c2430 draw_text.text_style.font_size: 24}
    Label{text: "A2App card template · synthetic demo" draw_text.color: #x5b6672 draw_text.text_style.font_size: 13}

    stage := RoundedView{width: Fill height: Fill flow: Down padding: 16 spacing: 12 draw_bg.color: #xffffff draw_bg.radius: 16 on_render: || {

        if depth == "glance" {
            View{width: Fill height: Fit flow: Right spacing: 8
                Label{text: "✉ Mail" draw_text.color: #x2f6fed draw_text.text_style.font_size: 13}
                View{width: Fill height: Fit}
                Label{text: "9:41" draw_text.color: #x5b6672 draw_text.text_style.font_size: 13}
            }
            Label{width: Fill height: Fit text: "Ana Rivera" draw_text.color: #x1c2430 draw_text.text_style.font_size: 16}
            Label{width: Fill height: Fit text: "Re: Contract signing — Friday?" draw_text.color: #x1c2430 draw_text.text_style.font_size: 20 draw_text.wrap: true}
            Label{width: Fill height: Fit text: "Can we sign by Friday? We'd send the revised terms first." draw_text.color: #x5b6672 draw_text.text_style.font_size: 14 draw_text.wrap: true}
            View{width: Fill height: Fit flow: Right spacing: 8
                AccentBtn{text: "Reply" on_click: || set_depth("expand")}
                NavBtn{text: "Expand ↗" on_click: || set_depth("expand")}
            }
            if archived { Label{width: Fill height: Fit text: "Archived (demo) — Undo in the expanded view" draw_text.color: #x5b6672 draw_text.text_style.font_size: 13 draw_text.wrap: true} }
        }

        if depth == "expand" {
            View{width: Fill height: Fit flow: Right spacing: 8
                Label{text: "MAIL" draw_text.color: #x2f6fed draw_text.text_style.font_size: 11}
                View{width: Fill height: Fit}
                Label{text: "9:41" draw_text.color: #x5b6672 draw_text.text_style.font_size: 13}
            }
            Label{width: Fill height: Fit text: "Re: Contract signing — Friday?" draw_text.color: #x1c2430 draw_text.text_style.font_size: 22 draw_text.wrap: true}
            View{width: Fill height: Fit flow: Right spacing: 6
                Label{text: "Ana Rivera" draw_text.color: #x1c2430 draw_text.text_style.font_size: 15}
                Label{text: "· ana@acme.demo" draw_text.color: #x5b6672 draw_text.text_style.font_size: 13}
            }
            SolidView{width: Fill height: 1 draw_bg.color: #xe2e7ec}
            Label{text: "AI-WRITTEN SUMMARY" draw_text.color: #x9aa4b0 draw_text.text_style.font_size: 11}
            Label{width: Fill height: Fit text: "Ana wants to sign by Friday and asked for the revised payment terms first." draw_text.color: #x1c2430 draw_text.text_style.font_size: 15 draw_text.wrap: true}
            Label{text: "Draft reply" draw_text.color: #x9aa4b0 draw_text.text_style.font_size: 12}
            reply_field := TextInput{width: Fill height: 48 padding: 12 empty_text: "Write a reply…" draw_bg.color: #xf7f9fb draw_bg.radius: 12 draw_text.color: #x1c2430 on_change: |t| on_field(t)}
            View{width: Fill height: Fit flow: Right spacing: 8
                AccentBtn{text: "Send (demo)" on_click: || do_send()}
                if archived { NavBtn{text: "Undo" on_click: || do_undo()} }
                if archived == false { GhostBtn{text: "Archive" on_click: || do_archive()} }
                NavBtn{text: "Open app" on_click: || set_depth("app")}
            }
            if sent_demo { Label{width: Fill height: Fit text: "Reply queued (demo) — no mail was sent." draw_text.color: #x1f9d55 draw_text.text_style.font_size: 13} }
            if archived { Label{width: Fill height: Fit text: "This demo message is archived. Undo restores it." draw_text.color: #x5b6672 draw_text.text_style.font_size: 13 draw_text.wrap: true} }
        }

        if depth == "app" {
            View{width: Fill height: Fit flow: Right spacing: 8
                NavBtn{text: "Inbox" on_click: || do_undo()}
                NavBtn{text: "Archived" on_click: || do_archive()}
                View{width: Fill height: Fit}
                Label{text: "Mail" draw_text.color: #x1c2430 draw_text.text_style.font_size: 15}
            }
            SolidView{width: Fill height: 1 draw_bg.color: #xe2e7ec}
            ScrollYView{width: Fill height: Fill flow: Down spacing: 8
                RoundedView{width: Fill height: Fit flow: Down padding: 12 spacing: 4 draw_bg.color: #xf7f9fb draw_bg.radius: 12
                    Label{text: "Ana Rivera" draw_text.color: #x5b6672 draw_text.text_style.font_size: 13}
                    Label{width: Fill height: Fit text: "Re: Contract signing — Friday?" draw_text.color: #x1c2430 draw_text.text_style.font_size: 16 draw_text.wrap: true}
                    Label{width: Fill height: Fit text: "Can we sign by Friday? We'd send the revised terms first." draw_text.color: #x5b6672 draw_text.text_style.font_size: 13 draw_text.wrap: true}
                    if archived { Label{text: "Archived (demo)" draw_text.color: #x2f6fed draw_text.text_style.font_size: 12} }
                }
                RoundedView{width: Fill height: Fit flow: Down padding: 12 spacing: 4 draw_bg.color: #xf7f9fb draw_bg.radius: 12
                    Label{text: "Design Weekly" draw_text.color: #x5b6672 draw_text.text_style.font_size: 13}
                    Label{width: Fill height: Fit text: "Your Thursday digest is ready" draw_text.color: #x1c2430 draw_text.text_style.font_size: 16 draw_text.wrap: true}
                    Label{width: Fill height: Fit text: "Five short reads on card UI." draw_text.color: #x5b6672 draw_text.text_style.font_size: 13 draw_text.wrap: true}
                }
                RoundedView{width: Fill height: Fit flow: Down padding: 12 spacing: 4 draw_bg.color: #xf7f9fb draw_bg.radius: 12
                    Label{text: "Team Bot" draw_text.color: #x5b6672 draw_text.text_style.font_size: 13}
                    Label{width: Fill height: Fit text: "Build passed on the release branch" draw_text.color: #x1c2430 draw_text.text_style.font_size: 16 draw_text.wrap: true}
                    Label{width: Fill height: Fit text: "All checks green." draw_text.color: #x5b6672 draw_text.text_style.font_size: 13 draw_text.wrap: true}
                }
            }
            NavBtn{text: "Back to expanded" on_click: || set_depth("expand")}
        }

    }}

    depth_status := Label{text: "Depth: L0 glance" draw_text.color: #x5b6672 draw_text.text_style.font_size: 13}
    View{width: Fill height: Fit flow: Right spacing: 8
        depth_glance := NavBtn{text: "Glance" on_click: || set_depth("glance")}
        depth_expand := NavBtn{text: "Expand" on_click: || set_depth("expand")}
        depth_open := NavBtn{text: "Open app" on_click: || set_depth("app")}
    }
